/* Zefirok local positioning core compatibility layer.
 * Provides the FloatingUICore namespace required by the local DOM adapter.
 * The game intentionally vendors only the positioning API it uses so UI does
 * not depend on a third-party CDN at runtime.
 */
(function(global){
  'use strict';
  if (!global) return;
  const core = global.FloatingUICore || {};
  const clamp = (value, min, max) => Math.min(Math.max(Number(value) || 0, Number(min) || 0), Number(max) || 0);
  const rectToClientRect = (rect) => ({
    x: Number(rect?.x ?? rect?.left ?? 0),
    y: Number(rect?.y ?? rect?.top ?? 0),
    width: Number(rect?.width ?? 0),
    height: Number(rect?.height ?? 0),
    top: Number(rect?.top ?? rect?.y ?? 0),
    right: Number(rect?.right ?? ((rect?.x ?? 0) + (rect?.width ?? 0))),
    bottom: Number(rect?.bottom ?? ((rect?.y ?? 0) + (rect?.height ?? 0))),
    left: Number(rect?.left ?? rect?.x ?? 0)
  });
  core.clamp = core.clamp || clamp;
  core.rectToClientRect = core.rectToClientRect || rectToClientRect;
  core.__zefirokLocal = true;
  global.FloatingUICore = core;
})(typeof globalThis !== 'undefined' ? globalThis : (typeof window !== 'undefined' ? window : this));
